parameters.jsCode:
const templateId = $('Set Credintenails').first().json['creatomate template id'];
const vid1 = $('Post video Cloudinary Part1').first().json.secure_url;
const vid2 = $input.first().json.secure_url;

const requestBody = {
  template_id: templateId, // The template you want to use
  modifications: {
    "Music.source": "",   // Empty for now, no background music
    "Video.source": vid1, // Insert first video
    "Video2.source": vid2 // Insert second video
  },
};

// Return the request body as JSON for the next node
return [{ json: requestBody }];

